const API=async()=>{const r=await fetch(new URL('./api-config.json',document.baseURI),{cache:'no-store'});const c=await r.json();if(!c.apiBase)throw Error('RSVP service is not configured yet.');return c.apiBase.replace(/\/$/,'')};
const dialog=document.createElement('dialog');dialog.style.cssText='border:1px solid #c6ae83;border-radius:24px;padding:24px;width:min(88vw,400px);max-height:85dvh;background:#fff9ef;color:#482c30;box-shadow:0 20px 80px #0006;z-index:2147483002';dialog.innerHTML='<form id="public-rsvp" style="display:grid;gap:14px"><button type="button" data-close style="justify-self:end">Close</button><h2 style="margin:0;font-family:Georgia">RSVP</h2><p>Strictly on invitation<br>This invitation allows two persons<br>Colour of the day: All White</p><label>Full name<input name="name" required maxlength="100" autocomplete="name"></label><label>Phone number<input name="phone" required type="tel" autocomplete="tel" maxlength="25"></label><label>Will you attend?<select name="attendance"><option value="yes">Joyfully accept</option><option value="no">Regretfully decline</option></select></label><label id="guest-field">Number of persons (including you)<select name="guests"><option value="1">1</option><option value="2">2</option></select></label><button type="submit">Send RSVP</button><p role="status" aria-live="polite" style="margin:0"></p></form>';document.body.append(dialog);const style=document.createElement('style');style.textContent='dialog::backdrop{background:#200c18aa;backdrop-filter:blur(8px)}#public-rsvp label{display:grid;gap:6px}#public-rsvp input,#public-rsvp select,#public-rsvp button{font:inherit;padding:12px;border:1px solid #cdb99a;border-radius:12px;background:#fff;color:#482c30}#public-rsvp button[type=submit]{background:#b18a50;color:white}';document.head.append(style);const f=dialog.querySelector('form'),status=f.querySelector('[role=status]');f.attendance.onchange=()=>{dialog.querySelector('#guest-field').hidden=f.attendance.value==='no'};dialog.querySelector('[data-close]').onclick=()=>dialog.close();document.addEventListener('click',e=>{if(e.target.closest('[data-invite="rsvp"],#rsvp-button')){e.preventDefault();e.stopImmediatePropagation();if(!dialog.open)dialog.showModal()}},true);f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;status.textContent='Saving…';try{const base=await API();const r=await fetch(base+'/api/rsvp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.elements.name.value,phone:f.phone.value,attendance:f.attendance.value,guests:f.attendance.value==='yes'?Number(f.guests.value):0})});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to save');status.textContent='Thank you! Your RSVP has been recorded.';f.reset();f.attendance.onchange()}catch(e){status.textContent=e.message+' Please try again.'}finally{b.disabled=false}};